/// rmu's directory on the tablet, outside the xochitl data dir and on the
/// same filesystem (`/home`), so staged files are moved into place with
/// `rename`.
pub const STATE_DIR: &str = "/home/root/.local/share/rmu";

/// The xochitl configuration file holding the cloud `devicetoken`.
pub const XOCHITL_CONF: &str = "/home/root/.config/remarkable/xochitl.conf";

/// The kernel's per-boot random id.
pub const BOOT_ID_PATH: &str = "/proc/sys/kernel/random/boot_id";

/// Name of the transient systemd unit (timer and service) of the watchdog.
pub const WATCHDOG_UNIT: &str = "rmu-hub-watchdog";

/// Where things live on a tablet. Always [`TabletPaths::default`] on a
/// real device; tests point it at scratch directories.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TabletPaths {
    /// The xochitl data dir.
    pub xochitl_dir: String,
    /// rmu's directory: state file, lock, watchdog marker, staging.
    pub state_dir: String,
    pub xochitl_conf: String,
    pub boot_id: String,
}

impl Default for TabletPaths {
    fn default() -> Self {
        Self {
            xochitl_dir: crate::xochitl::XOCHITL_DATA_DIR.to_string(),
            state_dir: STATE_DIR.to_string(),
            xochitl_conf: XOCHITL_CONF.to_string(),
            boot_id: BOOT_ID_PATH.to_string(),
        }
    }
}

impl TabletPaths {
    fn in_state(&self, name: &str) -> String {
        format!("{}/{name}", self.state_dir.trim_end_matches('/'))
    }

    /// The hub state file ([`crate::hub::model::TABLET_STATE_PATH`]).
    pub fn state_file(&self) -> String {
        self.in_state("hub.json")
    }

    /// The lock: a directory, created atomically by `mkdir`.
    pub fn lock_dir(&self) -> String {
        self.in_state("lock")
    }

    /// The lock owner record inside [`Self::lock_dir`].
    pub fn lock_owner(&self) -> String {
        self.in_state("lock/owner")
    }

    /// Held with `flock` by lock operations and guarded scripts, from
    /// the guard check to their last change.
    pub fn guard_flock(&self) -> String {
        self.in_state("guard.flock")
    }

    /// Left by the watchdog when it fires.
    pub fn watchdog_marker(&self) -> String {
        self.in_state("watchdog-fired")
    }

    /// Name of the armed systemd watchdog unit.
    pub fn watchdog_unit(&self) -> String {
        self.in_state("watchdog.unit")
    }

    /// Token the armed `sleep` watchdog must still find to fire.
    pub fn watchdog_token(&self) -> String {
        self.in_state("watchdog.token")
    }

    /// Process group and boot id of the armed `sleep` watchdog.
    pub fn watchdog_pid(&self) -> String {
        self.in_state("watchdog.pid")
    }

    /// Parent of every run's staging directory.
    pub fn staging_root(&self) -> String {
        self.in_state("staging")
    }

    /// One run's staging directory; staged files keep their
    /// xochitl-relative paths below it.
    pub fn staging_dir(&self, lock: &HeldLock) -> String {
        format!("{}/{}", self.staging_root(), lock.run())
    }
}

/// Errors of the device layer.
#[derive(Debug, Error)]
pub enum DeviceError {
    /// Another run holds the lock and it is not stale.
    #[error(
        "the tablet is locked by another rmu hub run ({0}); if that run is gone, retry with --break-lock"
    )]
    Locked(String),

    /// The lock changed between inspection and takeover; another run is
    /// acquiring it at the same time.
    #[error("the tablet lock changed while it was being acquired; another run is starting")]
    LockContended,

    /// Another run's hub operation held the guard `flock` for longer than
    /// a script waits for it.
    #[error("the tablet is busy with another rmu hub operation; try again later")]
    Busy,

    /// The lock no longer names this run: it was released or taken over.
    #[error("the hub lock on the tablet no longer belongs to this run; stopping")]
    LockLost,

    /// The watchdog fired (and restarted xochitl): this run must end.
    #[error("the watchdog on the tablet fired and restarted xochitl; stopping this run")]
    WatchdogFired,

    /// The tablet rebooted since this run took the lock: its watchdog is
    /// gone and xochitl may be running again, so this run must end.
    #[error("the tablet rebooted since this run took its lock; this run must end")]
    Rebooted,

    /// Refused: disarming the watchdog while xochitl is stopped would
    /// leave nothing to bring it back.
    #[error("refusing to disarm the watchdog while xochitl is stopped")]
    XochitlStopped,

    /// Refused: applying while xochitl runs would race its own writes.
    #[error("refusing to apply while xochitl is running")]
    XochitlRunning,

    /// Refused: stopping xochitl needs a watchdog armed by this run.
    #[error("refusing to stop xochitl without a watchdog armed by this run")]
    WatchdogNotArmed,

    /// A device command printed something rmu cannot interpret.
    #[error("unexpected output from the tablet ({operation}): {detail}")]
    Output {
        operation: &'static str,
        detail: String,
    },

    /// A path the device layer refuses to put into a transfer list.
    #[error("tablet path {0:?} cannot be transferred (control character or backslash)")]
    UnsupportedPath(String),

    /// A request the device layer refuses (e.g. a path listed twice).
    #[error("invalid device request: {0}")]
    InvalidRequest(String),

    /// A download did not deliver exactly the requested files.
    #[error("download from the tablet is incomplete: {0}")]
    Download(String),

    /// The content callback of a staging upload misbehaved.
    #[error("staging {path}: {detail}")]
    Stage { path: String, detail: String },

    /// An apply plan that cannot be executed as given.
    #[error("invalid apply plan: {0}")]
    InvalidPlan(String),

    /// The apply script stopped part-way. `applied` lists the documents
    /// it finished, in order; the rest may be half-applied (see
    /// "Restartability").
    #[error("apply on the tablet stopped after {} document(s): {reason}", .applied.len())]
    ApplyIncomplete { applied: Vec<DocId>, reason: String },

    /// xochitl did not start.
    #[error("xochitl did not start: {0}")]
    XochitlStart(String),

    /// The fake tablet detected a caller breaking the device contract
    /// (e.g. applying while xochitl runs). Never produced by a real
    /// tablet; end-to-end tests assert it never happens.
    #[error("device contract violated: {0}")]
    ContractViolation(String),
}

/// One non-directory entry of the xochitl data dir.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StatEntry {
    /// Relative to the xochitl data dir, `/`-separated; classify it with
    /// [`crate::hub::model::MirrorRules::classify`].
    pub path: String,
    /// Raw `st_mode` (file type and permission bits).
    pub mode: u32,
    pub stat: StatSignature,
}

const S_IFMT: u32 = 0o170_000;
const S_IFREG: u32 = 0o100_000;

impl StatEntry {
    /// Only regular files are ever mirrored.
    pub fn is_regular(&self) -> bool {
        self.mode & S_IFMT == S_IFREG
    }

    pub fn is_executable(&self) -> bool {
        self.is_regular() && self.mode & 0o111 != 0
    }
}

/// The stat pass: every non-directory entry of the xochitl data dir.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct StatListing {
    /// Sorted by path.
    pub entries: Vec<StatEntry>,
    /// Entries whose name contains a newline or a carriage return: they
    /// cannot be listed line by line, and no mirrored file can have such
    /// a name, so they are only counted (and reported as unrecognised
    /// files).
    pub unlisted: usize,
}

/// Model and firmware, for commit trailers and the mixed-model warning.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct DeviceInfo {
    pub model: Option<String>,
    pub firmware: Option<String>,
}

/// What a completed apply did.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ApplyReport {
    /// Documents applied, in plan order.
    pub applied: Vec<DocId>,
    /// Stats of the files written, taken after the device `sync`; sorted
    /// by path.
    pub written: Vec<StatEntry>,
    /// Device time after the writes (the racy-entry reference for
    /// `written`, see [`StatSignature::keep_in_manifest`]), in ns.
    pub recorded_at_ns: i64,
}

/// Content source for [`Tablet::stage`]: called once per file with a
/// sink that takes the file's exact size and a reader yielding exactly
/// that many bytes.
pub type StageContent<'a> =
    dyn FnMut(&XochitlPath, &mut dyn FnMut(u64, &mut dyn Read) -> Result<()>) -> Result<()> + 'a;

/// Receives each downloaded file: path, size, and a reader over exactly
/// that many bytes (unread bytes are skipped).
pub type DownloadVisitor<'a> = dyn FnMut(&XochitlPath, u64, &mut dyn Read) -> Result<()> + 'a;

/// Every tablet-side operation of the sync cycle. Operations taking a
/// [`HeldLock`] mutate the tablet and are guarded (see the module docs);
/// the others only read and are safe without the lock (`status`,
/// `--dry-run`).
pub trait Tablet {
    /// Take the hub lock. A held lock is taken over only if it is stale
    /// (the boot id changed, or the watchdog fired) or `break_lock` is
    /// set; never by age. Taking the lock clears a leftover watchdog
    /// marker (the old run's guard still fails: the lock is not its own).
    fn acquire_lock(&self, request: &LockRequest, break_lock: bool) -> Result<HeldLock>;

    /// Release the lock if it is still ours ([`DeviceError::LockLost`]
    /// otherwise).
    fn release_lock(&self, lock: &HeldLock) -> Result<()>;

    /// The lock as it is, without taking it (for `status`, and for the
    /// other mutating commands, which refuse while it is held).
    fn lock_state(&self) -> Result<LockState>;

    /// Check the guard without changing anything.
    fn check_guard(&self, lock: &HeldLock) -> Result<()>;

    /// Whether the watchdog marker is present.
    fn watchdog_fired(&self) -> Result<bool>;

    /// Arm, or re-arm, the watchdog: after `timeout` it tries to leave
    /// the marker, then runs `systemctl reset-failed xochitl.service;
    /// systemctl start xochitl.service` whether or not the marker could
    /// be written. Replaces any watchdog armed before (by any run), but
    /// only once the new one is armed. The watchdog records the run that
    /// armed it.
    fn arm_watchdog(&self, lock: &HeldLock, timeout: Duration) -> Result<()>;

    /// Disarm the watchdog this run armed; a watchdog armed by another
    /// run (before a takeover) is left alone. Refused while xochitl is
    /// stopped ([`DeviceError::XochitlStopped`]): the watchdog is what
    /// brings it back.
    fn disarm_watchdog(&self, lock: &HeldLock) -> Result<()>;

    /// `systemctl stop xochitl.service`. Refused unless a watchdog armed
    /// by this run is pending ([`DeviceError::WatchdogNotArmed`]).
    fn stop_xochitl(&self, lock: &HeldLock) -> Result<()>;

    /// `systemctl reset-failed xochitl.service`, then `start`. Returns the
    /// device time just before the start, in ns: the racy-entry reference
    /// for the stats taken before it (an earlier reference only drops
    /// more entries, so it is conservative; `0` if the reply was lost
    /// but xochitl is up). Allowed while the lock is ours or free (also
    /// after the watchdog fired, or after the state dir was lost): only
    /// another run's lock refuses it. Bringing the UI back is never
    /// otherwise refused.
    fn start_xochitl(&self, lock: &HeldLock) -> Result<i64>;

    fn xochitl_active(&self) -> Result<bool>;

    /// Whether the tablet is paired with the reMarkable cloud (the survey's
    /// `devicetoken` check; no credential leaves the device).
    fn cloud_paired(&self) -> Result<bool>;

    /// Where this tablet is reached from this computer (for `SshTablet`,
    /// the SSH destination and port): a local label for what rmu keeps
    /// about a tablet before it has a device id. No I/O.
    fn destination(&self) -> String;

    fn device_info(&self) -> Result<DeviceInfo>;

    /// One pass over the xochitl data dir: size, nanosecond mtime and
    /// ctime, and inode of every non-directory entry.
    fn stat_all(&self) -> Result<StatListing>;

    /// The same pass over the staging root: every file still staged, as
    /// `<run>/<xochitl path>`. After an interrupted apply this is what
    /// was not moved into place yet; a missing staging root lists
    /// nothing.
    fn staged_files(&self) -> Result<StatListing>;

    /// Stream the given files (one tar on a real tablet), calling `visit`
    /// once per file in the order the device sends them. Every requested
    /// file must arrive exactly once, as a regular file; an empty list
    /// makes no device call.
    fn download(&self, files: &[XochitlPath], visit: &mut DownloadVisitor<'_>) -> Result<()>;

    /// Read small files (re-reading `.metadata`/`.content`); `None` for
    /// a file that does not exist.
    fn read_files(&self, files: &[XochitlPath]) -> Result<BTreeMap<XochitlPath, Option<Vec<u8>>>>;

    /// SHA-256 (lowercase hex) of the given files in one batch; `None`
    /// for a file that does not exist.
    fn sha256(&self, files: &[XochitlPath]) -> Result<BTreeMap<XochitlPath, Option<String>>>;

    /// The hub state file, if the tablet has one.
    fn read_state(&self) -> Result<Option<TabletState>>;

    /// Atomically replace the hub state file and flush it to disk
    /// (device `sync`) before returning.
    fn write_state(&self, lock: &HeldLock, state: &TabletState) -> Result<()>;

    /// Delete the hub state file (`detach`), under the guard, and flush
    /// (device `sync`). An absent state file is not an error.
    fn remove_state(&self, lock: &HeldLock) -> Result<()>;

    /// Upload files into this run's staging directory (adding to what
    /// is already staged), in one transfer. Staged files are mode 0644;
    /// [`ApplyPlan`] carries each file's mode, set before it is moved.
    fn stage(
        &self,
        lock: &HeldLock,
        files: &[XochitlPath],
        content: &mut StageContent<'_>,
    ) -> Result<()>;

    /// Remove every run's staging directory.
    fn clear_staging(&self, lock: &HeldLock) -> Result<()>;

    /// Execute an apply plan (see [`ApplyPlan`]) with xochitl stopped
    /// (refused while it runs: [`DeviceError::XochitlRunning`]). Before
    /// any change: staging must be on the data dir's filesystem, every
    /// staged file must have its planned size (then gets its planned
    /// mode), and a device `sync`. Then per document, in plan order: the
    /// guard check, pages and payload, `.content`, `.metadata`; document
    /// deletions remove the whole `<uuid>`/`<uuid>.*` set (`.metadata`
    /// first). Each move is an atomic rename from staging. Ends with a
    /// device `sync` and a stat of every written file.
    ///
    /// A guard failure part-way ([`DeviceError::WatchdogFired`],
    /// [`DeviceError::LockLost`], [`DeviceError::Rebooted`]) is returned
    /// as such and may follow documents already applied; any other
    /// failure is [`DeviceError::ApplyIncomplete`], whose `applied` is a
    /// lower bound. Either way the run ends and reconciliation, not the
    /// error, decides what each document's files are.
    fn apply(&self, lock: &HeldLock, plan: &ApplyPlan) -> Result<ApplyReport>;
}

/// Watchdog timeouts are whole seconds, at least one.
fn timeout_secs(timeout: Duration) -> u64 {
    (timeout.as_secs() + u64::from(timeout.subsec_nanos() > 0)).max(1)
}

/// Paths in transfer lists are one per line and appear verbatim in
/// `sha256sum` output, so control characters (newlines) and backslashes
/// (which GNU `sha256sum` escapes) are refused. No mirrored path has
/// either. (A name like `-` is safe: scripts pass names as `./<name>`.)
fn transferable(path: &XochitlPath) -> std::result::Result<&str, DeviceError> {
    let text = path.as_str();
    if text.chars().any(|c| c.is_control() || c == '\\') {
        Err(DeviceError::UnsupportedPath(text.to_string()))
    } else {
        Ok(text)
    }
}

/// [`transferable`] over a whole list, which must not name a file twice.
fn transfer_paths(files: &[XochitlPath]) -> Result<Vec<&str>> {
    let paths = files
        .iter()
        .map(transferable)
        .collect::<std::result::Result<Vec<_>, _>>()?;
    let unique: std::collections::BTreeSet<&str> = paths.iter().copied().collect();
    if unique.len() != paths.len() {
        return Err(DeviceError::InvalidRequest("a file is listed twice".to_string()).into());
    }
    Ok(paths)
}

/// Yields exactly `remaining` bytes of `inner`, failing (and recording
/// why in `problem`) if `inner` ends early or has more: staging content
/// must match its declared size, or the archive (or file) would be
/// corrupt.
struct ExactReader<'r> {
    inner: &'r mut dyn Read,
    remaining: u64,
    problem: Option<String>,
}

impl<'r> ExactReader<'r> {
    fn new(inner: &'r mut dyn Read, size: u64) -> Self {
        Self {
            inner,
            remaining: size,
            problem: None,
        }
    }

    fn fail(&mut self, problem: String) -> std::io::Error {
        let error = std::io::Error::other(problem.clone());
        self.problem = Some(problem);
        error
    }
}

impl Read for ExactReader<'_> {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        if self.remaining == 0 {
            let mut probe = [0u8; 1];
            return match self.inner.read(&mut probe)? {
                0 => Ok(0),
                _ => Err(self.fail("content is longer than its declared size".to_string())),
            };
        }
        let limit = buf
            .len()
            .min(usize::try_from(self.remaining).unwrap_or(usize::MAX));
        let n = self.inner.read(&mut buf[..limit])?;
        if n == 0 && limit > 0 {
            let remaining = self.remaining;
            return Err(self.fail(format!(
                "content ended {remaining} byte(s) before its declared size"
            )));
        }
        self.remaining -= n as u64;
        Ok(n)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::hub::model::TABLET_STATE_PATH;

    #[test]
    fn exact_reader_enforces_the_declared_size() {
        let copy = |data: &[u8], size| {
            let mut source = data;
            let mut reader = ExactReader::new(&mut source, size);
            let mut out = Vec::new();
            let result = std::io::copy(&mut reader, &mut out);
            (result.is_ok(), out, reader.problem)
        };
        assert_eq!(copy(b"abc", 3), (true, b"abc".to_vec(), None));
        assert_eq!(copy(b"", 0), (true, Vec::new(), None));
        let (ok, _, problem) = copy(b"ab", 3);
        assert!(!ok && problem.unwrap().contains("1 byte(s) before"));
        let (ok, _, problem) = copy(b"abcd", 3);
        assert!(!ok && problem.unwrap().contains("longer"));
    }

    #[test]
    fn default_paths_match_the_model() {
        let paths = TabletPaths::default();
        assert_eq!(paths.state_file(), TABLET_STATE_PATH);
        assert_eq!(
            paths.xochitl_dir,
            "/home/root/.local/share/remarkable/xochitl"
        );
        assert_eq!(paths.lock_owner(), "/home/root/.local/share/rmu/lock/owner");
        // Staging must sit on the same filesystem as the data dir (/home).
        assert!(paths.staging_root().starts_with("/home/"));
    }

    #[test]
    fn timeouts_round_up_to_whole_seconds() {
        assert_eq!(timeout_secs(Duration::from_secs(300)), 300);
        assert_eq!(timeout_secs(Duration::from_millis(1500)), 2);
        assert_eq!(timeout_secs(Duration::ZERO), 1);
    }

    #[test]
    fn transfer_lists_refuse_newlines_and_backslashes() {
        let ok = XochitlPath::new("a b/c.rm").unwrap();
        assert_eq!(transferable(&ok).unwrap(), "a b/c.rm");
        ["x\ny", "x\\y", "x\ty"].into_iter().for_each(|bad| {
            let path = XochitlPath::new(bad).unwrap();
            assert!(matches!(
                transferable(&path),
                Err(DeviceError::UnsupportedPath(_))
            ));
        });
    }

    #[test]
    fn transfer_lists_refuse_duplicates() {
        let a = XochitlPath::new("a").unwrap();
        assert_eq!(transfer_paths(std::slice::from_ref(&a)).unwrap(), vec!["a"]);
        assert!(matches!(
            transfer_paths(&[a.clone(), a]),
            Err(crate::Error::HubDevice(DeviceError::InvalidRequest(_)))
        ));
    }

    #[test]
    fn stat_entry_mode_helpers() {
        let entry = |mode| StatEntry {
            path: "x".into(),
            mode,
            stat: StatSignature {
                size: 0,
                mtime_ns: 0,
                ctime_ns: 0,
                inode: 0,
            },
        };
        assert!(entry(0o100_644).is_regular());
        assert!(!entry(0o100_644).is_executable());
        assert!(entry(0o100_755).is_executable());
        assert!(!entry(0o120_777).is_regular());
    }
}
